// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/assistant/message", "require_user": true, "idempotent": false, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.orchestrator > "Validate body"
// POST /v1/assistant/message {text (required, up to 2000 characters), jurisdiction (default: the
// account's)}. Media ids come with phase 4.
const gw = $input.first().json;
const b = gw.ctx.body || {};
const user = gw.ctx.user || {};
const details = [];
for (const k of Object.keys(b)) if (!['text', 'jurisdiction'].includes(k)) details.push({ field: k, issue: 'unknown_field' });
const text = typeof b.text === 'string' ? b.text.trim() : '';
if (!text) details.push({ field: 'text', issue: 'required' });
else if (Array.from(text).length > 2000) details.push({ field: 'text', issue: 'too_long', max: 2000 });
const jurisdiction = b.jurisdiction === undefined ? (user.jurisdiction_code || null) : b.jurisdiction;
if (jurisdiction !== null && (typeof jurisdiction !== 'string' || !/^[A-Z]{2}(-[A-Z0-9]{1,3})?$/.test(jurisdiction))) details.push({ field: 'jurisdiction', issue: 'invalid_format' });
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
return [{ json: { ok: true, gw, text, jurisdiction, today: new Date().toISOString().slice(0, 10) } }];

// wf.orchestrator > "Router input" (P1, active version)
const v = $('Validate body').first().json;
return [{ json: { prompt: 'P1_router', version: null, model: null, vars: { message: v.text, user_jurisdiction: v.jurisdiction || 'unknown' } } }];

// wf.orchestrator > "Decide route" (deterministic, spec 8.1). Output index for the Switch:
// 0 search_listings, 1 ask a clarifying question (needs_clarification, or confidence below
// router.min_confidence), 2 a supported intent whose agent comes in a later phase,
// 3 smalltalk_or_unsupported, 4 the router failed.
const r = $input.first().json;
const v = $('Validate body').first().json;
const min = Number($('Context').first().json.min_confidence ?? 0.6);
const step = { agent: 'A0_orchestrator', prompt_version_id: r.prompt_version_id || null, model: r.model || null,
  input: { chars: Array.from(v.text).length }, output: r.ok ? r.output : { error_code: r.error_code },
  latency_ms: r.latency_ms, tokens_in: r.tokens_in || 0, tokens_out: r.tokens_out || 0,
  error: r.ok ? null : `${r.error_code}${r.detail ? ': ' + String(r.detail).slice(0, 200) : ''}` };
// Text service result (language, PII), recorded as its own step; the request text is not stored (D-062).
const tr = $('Text analysis').first().json || {};
const tb = tr.body && typeof tr.body === 'object' ? tr.body : null;
const textStep = { agent: 'A0_text', model: tb ? tb.backend : null, input: { chars: Array.from(v.text).length },
  output: tb ? { language: tb.language.language, script: tb.language.script, method: tb.language.method,
    pii_counts: tb.pii ? tb.pii.counts : {}, ner: tb.pii ? tb.pii.ner : false } : null,
  latency_ms: tb ? Math.round(tb.ms) : null, tokens_in: 0, tokens_out: 0,
  error: tb ? null : `text service answered ${tr.statusCode || tr.code || 'nothing'}` };
let route;
if (!r.ok) route = 4;
else if (r.output.needs_clarification || r.output.confidence < min) route = 1;
else if (r.output.intent === 'search_listings') route = 0;
else if (r.output.intent === 'smalltalk_or_unsupported') route = 3;
else route = 2;
const o = r.ok ? r.output : {};
const hint = ['TN', 'FR', 'GB'].includes(o.jurisdiction_hint) ? o.jurisdiction_hint : null;
return [{ json: { route, router: o, call_error: !!r.call_error, steps: [textStep, step],
  detected_language: tb ? tb.language.language : null,
  extract: { text: v.text, jurisdiction: hint || v.jurisdiction, today: v.today } } }];

// wf.orchestrator > "Match input": search filters from the extracted profile.
const x = $input.first().json;
if (!x.ok) return [{ json: { skip: true, x } }];
const p = x.profile;
const a = x.anchor && x.anchor.status === 'found' ? x.anchor.place : null;
return [{ json: { skip: false, jurisdiction: x.search_jurisdiction, q: $('Validate body').first().json.text,
  max_rent_minor: p.budget_max_minor, currency: p.currency, budget_period: p.budget_period,
  lat: a ? a.lat : null, lng: a ? a.lng : null, place: null, radius_m: null, limit: 10 } }];

// wf.orchestrator > "Search result"
const v = $('Validate body').first().json;
const d = $('Decide route').first().json;
const x = $('Extract profile').first().json;
const steps = [...d.steps, ...(x.steps || [])];
const mi = $('Match input').first().json;
if (mi.skip) {
  const status = x.error_code === 'UPSTREAM_UNAVAILABLE' ? 503 : 200;
  if (status === 503) return [{ json: { ok: false, gw: v.gw, status, steps, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'The language model is unavailable', details: [] } } }];
  return [{ json: { ok: true, gw: v.gw, status: 200, steps, data: { intent: 'search_listings', language: d.router.language,
    status: 'profile_failed', profile: null, results: [], warnings: ['profile_extraction_failed'] } } }];
}
const m = $input.first().json;
steps.push({ agent: 'A3_match', model: m.applied && m.applied.vector ? 'bge-m3' : null, input: { mode: m.mode },
  output: { count: m.count, warnings: m.warnings }, latency_ms: m.timings ? m.timings.total_ms : null,
  tool_calls: [{ tool: 'app.search_public', db_ms: m.timings && m.timings.db_ms, embed_ms: m.timings && m.timings.embed_ms }] });
return [{ json: { ok: true, gw: v.gw, status: 200, steps, meta: { timings: m.timings },
  data: { intent: 'search_listings', language: d.router.language, status: m.ok ? 'results' : 'search_failed',
          profile: x.profile, anchor: x.anchor, results: m.ok ? m.results : [], count: m.ok ? m.count : 0,
          applied: m.applied || null, warnings: [...(x.warnings || []), ...(m.warnings || [])], data_attribution: ['openstreetmap'] } } }];

// wf.orchestrator > "Other intents": clarification, intents of later phases, smalltalk, router failure.
// Status codes, not sentences (spec 17.1); the clarifying question is the router's, in the user's language.
const v = $('Validate body').first().json;
const d = $input.first().json;
const o = d.router || {};
if (d.route === 4) {
  if (d.call_error) return [{ json: { ok: false, gw: v.gw, status: 503, steps: d.steps, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'The language model is unavailable', details: [] } } }];
  return [{ json: { ok: true, gw: v.gw, status: 200, steps: d.steps, data: { intent: null, status: 'not_understood', language: null } } }];
}
const status = { 1: 'clarification_needed', 2: 'not_available_yet', 3: 'unsupported' }[d.route];
return [{ json: { ok: true, gw: v.gw, status: 200, steps: d.steps, data: { intent: o.intent, language: o.language,
  status, confidence: o.confidence, clarifying_question: d.route === 1 ? (o.clarifying_question || null) : null } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
